arguments.code:
const frames = page.frames();
const results = [];
for (const f of frames) {
  try {
    const banner = await f.$('.instui-banner');
    if (banner) {
      const info = await f.evaluate((el) => {
        const heading = el.querySelector('h2, .instui-heading, [class*="heading"]');
        const cs = heading ? getComputedStyle(heading) : null;
        const bs = getComputedStyle(el);
        return {
          html: el.outerHTML,
          headingStyles: cs ? {
            fontSize: cs.fontSize, fontWeight: cs.fontWeight, textAlign: cs.textAlign,
            gridColumn: cs.gridColumn, gridRow: cs.gridRow, margin: cs.margin, display: cs.display, width: cs.width
          } : null,
          bannerStyles: { display: bs.display, gridTemplateColumns: bs.gridTemplateColumns }
        };
      }, banner);
      results.push({url: f.url(), info});
    }
  } catch (e) {
    results.push({url: f.url(), error: String(e)});
  }
