const frames = page.frames();
let info = null;
for (const f of frames) {
  const btn = await f.$('.instui-button');
  if (btn) {
    await btn.hover();
    info = await f.evaluate((el) => {
      const cs = getComputedStyle(el);
      return { borderColor: cs.borderColor, color: cs.color, background: cs.backgroundColor };
    }, btn);
  }
}
return JSON.stringify(info);

